import java.nio.file.*;

/**
 * Generates src/java_cased_letters.rs: the code points of the general categories Lu, Ll and Lt (`Character.getType`) as
 * inclusive ranges, the Unicode data of `ConditionalSpecialCasing.isCased` (final sigma).
 * Usage: crates/mc-core/tests/fixtures/java_case/gen.sh
 * Output: crates/mc-core/src/java_cased_letters.rs
 */
public class GenCasedLetters {
   static boolean cased(int cp) {
      int t = Character.getType(cp);
      return t == Character.UPPERCASE_LETTER || t == Character.LOWERCASE_LETTER || t == Character.TITLECASE_LETTER;
   }

   public static void main(String[] args) throws Exception {
      StringBuilder out = new StringBuilder();
      out.append("//! Generated by tests/fixtures/java_case/GenCasedLetters.java (JDK ").append(System.getProperty("java.version")).append("): do not edit.\n\n");
      out.append("/// Inclusive code point ranges of the Unicode categories Lu, Ll and Lt (`Character.getType`).\n");
      out.append("pub(crate) static CASED_LETTERS: &[(u32, u32)] = &[\n");
      int start = -1;
      for (int cp = 0; cp <= 0x110000; cp++) {
         boolean c = cp <= 0x10ffff && cased(cp);
         if (c && start < 0) start = cp;
         if (!c && start >= 0) {
            out.append(String.format("    (0x%04X, 0x%04X),\n", start, cp - 1));
            start = -1;
         }
      }
      out.append("];\n");
      Files.writeString(Path.of(args[0]), out.toString());
   }
}
